package com.example.bodega.venta.service;
import com.example.bodega.common.exception.*; import com.example.bodega.inventario.enums.TipoMovimiento; import com.example.bodega.inventario.service.InventarioService; import com.example.bodega.producto.entity.Producto; import com.example.bodega.producto.repository.ProductoRepository; import com.example.bodega.usuario.entity.Usuario; import com.example.bodega.venta.dto.*; import com.example.bodega.venta.entity.*; import com.example.bodega.venta.enums.EstadoVenta; import com.example.bodega.venta.mapper.VentaMapper; import com.example.bodega.venta.repository.VentaRepository;
import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor
public class VentaService { private final VentaRepository ventas; private final ProductoRepository productos; private final InventarioService inventario;
    @Transactional public VentaResponse crear(VentaRequest r,String key,Long usuarioId){if(key==null||key.isBlank())throw new BusinessException("La cabecera Idempotency-Key es obligatoria.");var previa=ventas.findByIdempotencyKey(key);if(previa.isPresent())return VentaMapper.toResponse(previa.get());Set<Long> ids=new HashSet<>();for(var d:r.detalles())if(!ids.add(d.productoId()))throw new BusinessException("Un producto no puede repetirse en el detalle.");List<Producto> bloqueados=productos.findAllByIdForUpdate(ids);if(bloqueados.size()!=ids.size())throw new NotFoundException("Uno o mas productos no existen.");Map<Long,Producto> porId=new HashMap<>();bloqueados.forEach(p->porId.put(p.getId(),p));Usuario usuario=inventario.usuario(usuarioId);Venta venta=new Venta();venta.setNumero("V-"+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase());venta.setUsuario(usuario);venta.setFecha(Instant.now());venta.setMetodoPago(r.metodoPago());venta.setEstado(EstadoVenta.COMPLETADA);venta.setIdempotencyKey(key.trim());BigDecimal total=BigDecimal.ZERO;for(var item:r.detalles()){Producto p=porId.get(item.productoId());if(!p.isActivo())throw new BusinessException("El producto esta inactivo: "+p.getNombre());if(p.getStockActual()<item.cantidad())throw new ConflictException("Stock insuficiente para el producto: "+p.getNombre());BigDecimal subtotal=p.getPrecioVenta().multiply(BigDecimal.valueOf(item.cantidad()));DetalleVenta d=new DetalleVenta();d.setProducto(p);d.setCantidad(item.cantidad());d.setPrecioUnitario(p.getPrecioVenta());d.setSubtotal(subtotal);venta.addDetalle(d);total=total.add(subtotal);}venta.setTotal(total);ventas.save(venta);for(DetalleVenta d:venta.getDetalles())inventario.apply(d.getProducto(),TipoMovimiento.VENTA,d.getCantidad(),false,"Venta "+venta.getNumero(),usuario,venta);return VentaMapper.toResponse(venta);}
    @Transactional public VentaResponse anular(Long id,AnulacionRequest r,Long usuarioId){Venta venta=ventas.findById(id).orElseThrow(()->new NotFoundException("Venta no encontrada."));if(venta.getEstado()==EstadoVenta.ANULADA)return VentaMapper.toResponse(venta);List<Long> ids=venta.getDetalles().stream().map(d->d.getProducto().getId()).sorted().toList();Map<Long,Producto> productosBloqueados=new HashMap<>();productos.findAllByIdForUpdate(ids).forEach(p->productosBloqueados.put(p.getId(),p));Usuario usuario=inventario.usuario(usuarioId);for(DetalleVenta d:venta.getDetalles())inventario.apply(productosBloqueados.get(d.getProducto().getId()),TipoMovimiento.ANULACION_VENTA,d.getCantidad(),true,"Anulacion "+venta.getNumero()+": "+r.motivo().trim(),usuario,venta);venta.setEstado(EstadoVenta.ANULADA);venta.setAnuladaAt(Instant.now());venta.setAnuladaPor(usuario);venta.setMotivoAnulacion(r.motivo().trim());return VentaMapper.toResponse(venta);}
    @Transactional(readOnly=true) public VentaResponse obtener(Long id){return VentaMapper.toResponse(ventas.findById(id).orElseThrow(()->new NotFoundException("Venta no encontrada.")));}
    @Transactional(readOnly=true) public Page<VentaResponse> listar(LocalDate desde, LocalDate hasta, EstadoVenta estado, Long usuarioId, Pageable pageable) { if (desde != null && hasta != null && hasta.isBefore(desde)) throw new BusinessException("Rango de fechas invalido."); Instant inicio = desde == null ? null : desde.atStartOfDay(ZoneOffset.UTC).toInstant(); Instant fin = hasta == null ? null : hasta.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant(); return ventas.search(inicio, fin, estado, usuarioId, pageable).map(VentaMapper::toResponse); }
}
